import{_ as a,o as s,c as n,a8 as o}from"./chunks/framework.BppdKxCY.js";const u=JSON.parse('{"title":"EP.61 依赖供应链暗门","description":"","frontmatter":{},"headers":[],"relativePath":"comics/EP.61-dependency-supply-chain.md","filePath":"comics/EP.61-dependency-supply-chain.md","lastUpdated":1793421673000}'),t={name:"comics/EP.61-dependency-supply-chain.md"};function i(l,e,p,c,d,r){return s(),n("div",null,[...e[0]||(e[0]=[o(`<h1 id="ep-61-依赖供应链暗门" tabindex="-1">EP.61 依赖供应链暗门 <a class="header-anchor" href="#ep-61-依赖供应链暗门" aria-label="Permalink to &quot;EP.61 依赖供应链暗门&quot;">​</a></h1><blockquote><p>对应正文：<a href="./../66-dependency-governance">第六十六部分 · 第三方依赖治理与高危漏洞修复</a></p></blockquote><h2 id="剧情回顾" tabindex="-1">剧情回顾 <a class="header-anchor" href="#剧情回顾" aria-label="Permalink to &quot;剧情回顾&quot;">​</a></h2><ul><li><strong>第 1 格</strong>：标签君为了省事随手 <code>pnpm add tiny-lib</code>，装完 CI 凭据就被调用了——罪魁祸首是一条 <code>postinstall: &quot;curl ... | sh&quot;</code>。安装脚本在 <code>npm install</code> 阶段就拥有与开发者/CI 相同的权限。</li><li><strong>第 2 格</strong>：码叔摆出四层治理闭环——准入（评分/硬门槛/白名单）→ 锁定（lockfile/私有 registry）→ 监测（audit/SBOM/漏洞情报）→ 响应（定级/SLA/修复路径）。准入管源头，锁定管一致，监测管时效，响应管止损。</li><li><strong>第 3 格</strong>：像素酱跑了一遍准入评分器：下载量低、730 天未发布、带安装脚本、传递依赖深、已废弃——直接 100 分 reject。硬门槛优先于总分，废弃包一票否决。</li><li><strong>第 4 格</strong>：码叔结案——扫描器的声明严重度不等于有效风险，要按运行环境、可达性、利用成熟度折减加成；Critical 先 24 小时止血再 72 小时修复，路径按「升级 → 覆盖 → 补丁 → 替换 → 隔离 → 接受」逐级选择。</li></ul><h2 id="知识点拆解" tabindex="-1">知识点拆解 <a class="header-anchor" href="#知识点拆解" aria-label="Permalink to &quot;知识点拆解&quot;">​</a></h2><h3 id="第-1-格-·-安装脚本就是一次任意代码执行" tabindex="-1">第 1 格 · 安装脚本就是一次任意代码执行 <a class="header-anchor" href="#第-1-格-·-安装脚本就是一次任意代码执行" aria-label="Permalink to &quot;第 1 格 · 安装脚本就是一次任意代码执行&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ pnpm add tiny-lib</span></span>
<span class="line"><span>&quot;postinstall&quot;: &quot;curl ... | sh&quot;</span></span>
<span class="line"><span>→ CI token / SSH key 被读取外传</span></span></code></pre></div><p>很多人以为「只是装个依赖，又没运行它」——但 npm 生命周期脚本会在安装阶段自动执行。攻击者只需在恶意版本里加一条 <code>postinstall</code>，就能读取 <code>.env</code>、SSH key、CI token，甚至写入构建产物。防御：安装脚本白名单（<code>onlyBuiltDependencies</code>）、<code>--ignore-scripts</code>、引入前读 <code>package.json</code> 的 <code>scripts</code>。正文展开见 <a href="./../66-dependency-governance#_66-2-依赖准入-评分、硬门槛与白名单审批">66.2</a> 与 <a href="./../66-dependency-governance#_66-3-可复现安装与供应链加固">66.3</a>。</p><h3 id="第-2-格-·-四层治理闭环" tabindex="-1">第 2 格 · 四层治理闭环 <a class="header-anchor" href="#第-2-格-·-四层治理闭环" aria-label="Permalink to &quot;第 2 格 · 四层治理闭环&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>准入 → 锁定 → 监测 → 响应</span></span>
<span class="line"><span>  ↑                    │</span></span>
<span class="line"><span>  └──── 复盘反哺 ←─────┘</span></span></code></pre></div><ul><li><strong>准入</strong>回答「这个包能不能进来」：五维评分 + 硬门槛 + 审批；</li><li><strong>锁定</strong>回答「每次装出来是否一样」：lockfile、<code>--frozen-lockfile</code>、scope 级 registry；</li><li><strong>监测</strong>回答「后来出事了多久知道」：CI audit、SBOM、漏洞情报；</li><li><strong>响应</strong>回答「出事时多快、按什么路径修」：有效严重度 + SLA + 修复阶梯。</li></ul><p>四层里最容易被跳过的是准入——先装上再说，等 audit 报警时迁移成本已经很高。完整模型见 <a href="./../66-dependency-governance#_66-1-依赖风险全景与四层治理模型">66.1</a>。</p><h3 id="第-3-格-·-准入评分器一跑就露馅" tabindex="-1">第 3 格 · 准入评分器一跑就露馅 <a class="header-anchor" href="#第-3-格-·-准入评分器一跑就露馅" aria-label="Permalink to &quot;第 3 格 · 准入评分器一跑就露馅&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>下载量 &lt; 1万      +25</span></span>
<span class="line"><span>730 天未发布     +25</span></span>
<span class="line"><span>postinstall 脚本  +15</span></span>
<span class="line"><span>传递依赖 &gt; 10    +15</span></span>
<span class="line"><span>已废弃            +30</span></span>
<span class="line"><span>→ score 100 → reject</span></span></code></pre></div><p>评分只是把「靠不靠谱」拆成可复核的维度；真正不能放过的是硬门槛：安装脚本必须人工复核、废弃包直接拒绝、copyleft 至少走法务评审。可运行实现见 <a href="../examples/66-01-dependency-admission.ts">66-01-dependency-admission.ts</a>（6 组硬断言）。评分维度与审批流程见 <a href="./../66-dependency-governance#_66-2-依赖准入-评分、硬门槛与白名单审批">66.2</a>。</p><h3 id="第-4-格-·-先止血-再按路径修复" tabindex="-1">第 4 格 · 先止血，再按路径修复 <a class="header-anchor" href="#第-4-格-·-先止血-再按路径修复" aria-label="Permalink to &quot;第 4 格 · 先止血，再按路径修复&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>有效严重度 = 声明 − 环境/可达 + 利用</span></span>
<span class="line"><span>Critical → 24h 止血 / 72h 修复</span></span>
<span class="line"><span>High     → 72h 止血 / 7d 修复</span></span>
<span class="line"><span>路径     升级→覆盖→补丁→替换→隔离→接受</span></span></code></pre></div><p>扫描器给的 CVSS 是通用危害，不是你的实际风险：仅构建期依赖降 2 级，运行时但业务不可达降 1 级，已有活跃利用升 1 级。修复按成本从低到高走，能升级就不打补丁，能打补丁就不替换；无补丁且不可达时才允许「限时风险接受」，必须有证据、期限和审批人。可运行实现见 <a href="../examples/66-02-vuln-remediation.ts">66-02-vuln-remediation.ts</a>（6 组硬断言），完整 SOP 见 <a href="./../66-dependency-governance#_66-5-高危漏洞修复-sop">66.5</a>。</p><h2 id="坑点清单" tabindex="-1">坑点清单 <a class="header-anchor" href="#坑点清单" aria-label="Permalink to &quot;坑点清单&quot;">​</a></h2><blockquote><p>🔗 正文对照：<a href="./../66-dependency-governance#_66-7-本章避坑清单">《66.7 本章避坑清单》</a></p></blockquote><ol><li><strong>不提交 lockfile</strong>：本地和 CI 装出不同依赖树，漏洞与故障都无法复现。提交 <code>pnpm-lock.yaml</code>，CI 用 <code>--frozen-lockfile</code>。</li><li><strong>忽略安装脚本</strong>：<code>npm install</code> 等同于执行任意代码。安装脚本白名单 + <code>--ignore-scripts</code> + 引入前读源码。</li><li><strong>私有包无 scope</strong>：同名抢注（依赖混淆）会把公网恶意包装进来。scope 命名 + scope 级 registry + lockfile 校验。</li><li><strong><code>audit fix --force</code> 一把梭</strong>：主版本全升，破坏性变更无人评估。逐条选修复路径，major 单独回归。</li><li><strong>只看声明严重度</strong>：不可达漏洞占满排期，真高危被淹没。按环境、可达性、利用成熟度算有效严重度。</li><li><strong>无补丁就默认接受风险</strong>：漏洞长期存在且无审批留痕。优先替换/隔离，接受必须带证据、期限、审批人。</li><li><strong>忽略 devDependency 漏洞</strong>：构建机同样有源码和 CI 凭据。开发/构建依赖也要纳入监测与修复。</li></ol><h2 id="自测-3-题" tabindex="-1">自测 3 题 <a class="header-anchor" href="#自测-3-题" aria-label="Permalink to &quot;自测 3 题&quot;">​</a></h2><p><strong>1. 为什么「只是安装、没有调用」的依赖也可能导致凭据泄漏？</strong></p><details><summary>参考答案</summary><p>因为 npm 生命周期脚本（<code>preinstall</code>/<code>install</code>/<code>postinstall</code>）会在安装阶段自动执行，拥有与开发者或 CI 进程相同的权限：可以读 <code>.env</code>、SSH key、CI token，改写文件或发起网络请求。攻击者只需在恶意版本里加一条 <code>postinstall</code> 就能完成窃取。防御手段是安装脚本白名单（pnpm 的 <code>onlyBuiltDependencies</code>）、<code>--ignore-scripts</code>，以及引入前人工审查 <code>scripts</code> 字段。</p></details><p><strong>2. 声明严重度与有效严重度有什么区别？为什么不能直接按扫描器排序修复？</strong></p><details><summary>参考答案</summary><p>声明严重度来自 CVSS/扫描器，描述漏洞本身的通用危害；有效严重度结合运行环境、业务可达性、暴露面与利用成熟度，描述「对当前项目」的实际风险。仅构建期依赖不进入用户浏览器、运行时依赖但业务不可达，都应折减；已有活跃利用要加成。如果直接按声明严重度排序，大量不可达漏洞会占满修复资源，真正高危反而被淹没。</p></details><p><strong>3. 传递依赖出现高危漏洞、上游还没发修复版，应该按什么顺序处置？</strong></p><details><summary>参考答案</summary><p>先止血（功能开关/网关拦截/回滚），再按成本从低到高选择：① <code>pnpm.overrides</code> 强制传递依赖到已修复版本（若上游已发布但未提升）；② <code>patchedDependencies</code>/patch-package 打最小补丁并跟踪上游 issue；③ 替换直接依赖为维护活跃的替代库；④ 隔离/下线受影响功能；⑤ 有不可达证据时做限时风险接受（记录证据、期限、审批人）。修复后必须复跑 audit、跑回归、审查 lockfile diff，并更新台账与 SBOM。</p></details>`,28)])])}const g=a(t,[["render",i]]);export{u as __pageData,g as default};
